6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":4432,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 18.1\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T6ee,"])self.__next_f.push([1,"Actually the Bhagavad-gītā is finished in seventeen chapters. The Eighteenth Chapter is a supplementary summarization of the topics discussed before. In every chapter of Bhagavad-gītā, Lord Kṛṣṇa stresses that devotional service unto the Supreme Personality of Godhead is the ultimate goal of life. This same point is summarized in the Eighteenth Chapter as the most confidential path of knowledge. In the first six chapters, stress was given to devotional service: yoginām api sarveṣām … “Of all yogīs or transcendentalists, one who always thinks of Me within himself is best.” In the next six chapters, pure devotional service and its nature and activity were discussed. In the third six chapters, knowledge, renunciation, the activities of material nature and transcendental nature, and devotional service were described. It was concluded that all acts should be performed in conjunction with the Supreme Lord, represented by the words oṁ tat sat, which indicate Viṣṇu, the Supreme Person. The third part of Bhagavad-gītā has shown that devotional service, and nothing else, is the ultimate purpose of life. This has been established by citing past ācāryas and the Brahma-sūtra, the Vedānta-sūtra. Certain impersonalists consider themselves to have a monopoly on the knowledge of Vedānta-sūtra, but actually the Vedānta-sūtra is meant for understanding devotional service, for the Lord Himself is the composer of the Vedānta-sūtra, and He is its knower. That is described in the Fifteenth Chapter. In every scripture, every Veda, devotional service is the objective. That is explained in Bhagavad-gītā."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":4432,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"1\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXT 1\",\"advanced_view_url_path\":\"/en/library/bg/18/advanced-view/#bb3892\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/18/1/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/18/1/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/18/1/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/18/1/\"},{\"display_name\":\"English\",\"language_code\":\"en\",\"e