\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":4442,\"bb\":3900,\"url_path\":\"/en/library/bg/18/2/b3900/\",\"body_value\":\"śrī-bhagavān uvāca
kāmyānāṁ karmaṇāṁ nyāsaṁ
sannyāsaṁ kavayo viduḥ
sarva-karma-phala-tyāgaṁ
prāhus tyāgaṁ vicakṣaṇāḥ\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":4443,\"bb\":3901,\"url_path\":\"/en/library/bg/18/2/b3901/\",\"shadow_value\":\"śrī-bhagavān uvāca – the Supreme Personality of Godhead said; kāmyānām – with desire; karmaṇām – of activities; nyāsam – renunciation; sannyāsam – the renounced order of life; kavayaḥ – the learned; viduḥ – know; sarva – of all; karma – activities; phala – of results; tyāgam – renunciation; prāhuḥ – call; tyāgam – renunciation; vicakṣaṇāḥ – the experienced.\",\"word_for_word_value\":[{\"word\":\"śrī-bhagavān uvāca\",\"translation\":\"the Supreme Personality of Godhead said\"},{\"word\":\"kāmyānām\",\"translation\":\"with desire\"},{\"word\":\"karmaṇām\",\"translation\":\"of activities\"},{\"word\":\"nyāsam\",\"translation\":\"renunciation\"},{\"word\":\"sannyāsam\",\"translation\":\"the renounced order of life\"},{\"word\":\"kavayaḥ\",\"translation\":\"the learned\"},{\"word\":\"viduḥ\",\"translation\":\"know\"},{\"word\":\"sarva\",\"translation\":\"of all\"},{\"word\":\"karma\",\"translation\":\"activities\"},{\"word\":\"phala\",\"translation\":\"of results\"},{\"word\":\"tyāgam\",\"translation\":\"renunciation\"},{\"word\":\"prāhuḥ\",\"translation\":\"call\"},{\"word\":\"tyāgam\",\"translation\":\"renunciation\"},{\"word\":\"vicakṣaṇāḥ\",\"translation\":\"the experienced\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":4444,\"bb\":3902,\"url_path\":\"/en/library/bg/18/2/b3902/\",\"body_value\":\"The Supreme Personality of Godhead said: The giving up of activities that are based on material desire is what great learned men call the renounced order of life [sannyāsa]. And giving up the results of all activities is what the wise call renunciation [tyāga].\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":4445,\"bb\":3903,\"url_path\":\"/en/library/bg/18/2/b3903/\",\"body_value\":\"The performance of activities for results has to be given up. This is the instruction of Bhagavad-gītā. But activities leading to advanced spiritual knowledge are not to be given up. This will be made clear in the next verses. In the Vedic literature there are many prescriptions of methods for performing sacrifice for some particular purpose. There are certain sacrifices to perform to attain a good son or to attain elevation to the higher planets, but sacrifices prompted by desires should be stopped. However, sacrifice for the purification of one’s heart or for advancement in the spiritual science should not be given up.\"}]}],\"short_title\":\"Bg. 18.2\",\"medium_title\":\"Bhagavad-gītā As It Is 18.2\"},\"locale\":\"en\",\"activeView\":\"$6:props:activeView\"}]}],\"$L25\",\"$L26\",\"$L27\"]}]\n"])self.__next_f.push([1,"29:I[83068,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n2f:I[78455,[\"/_next/static/chunks/130enlymdm.jk.js\",\"/_next/static/chunks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n25:[\"$\",\"div\",null,{\"className\":\"px-4 py-4 w-full max-w-screen-xl mx-auto md:px-8 mb-3\",\"children\":[[\"$\",\"nav\",null,{\"aria-label\":\"Breadcrumb\",\"className\":\"breadcrumb mb-8